+import type {
+  IncomingMessage,
+  OutgoingMessage,
+  ListSessionsMessage,
+  SessionListMessage,
+  SessionSummaryFrame,
+} from '../index.js';
+import type {SessionCursor} from './sessionStore.js';
+
+describe('WebSocket message types', () => {
+  it('pins that existing incoming and outgoing message literals remain assignable', () => {
+    const userMessage: IncomingMessage = {type: 'user_message', content: 'hello'};
+    const ping: IncomingMessage = {type: 'ping', timestamp: 123456};
+    const incoming: IncomingMessage[] = [userMessage, ping];
+
+    const connected: OutgoingMessage = {
+      type: 'connected',
+      sessionId: 's1',
+      message: 'welcome',
+      examplePrompts: [],
+    };
+    const upsert: OutgoingMessage = {
+      type: 'entry_upsert',
+      index: 0,
+      entry: {role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'},
+    };
+    const delta: OutgoingMessage = {type: 'entry_delta', index: 1, delta: 'world'};
+    const commit: OutgoingMessage = {type: 'entry_commit', index: 1};
+    const skip: OutgoingMessage = {type: 'entry_skip', index: 2};
+    const error: OutgoingMessage = {type: 'error', code: 'SERVER_ERROR', message: 'failed'};
+    const pong: OutgoingMessage = {type: 'pong', timestamp: 123456};
+    const streamEnd: OutgoingMessage = {type: 'stream_end'};
+    const outgoing: OutgoingMessage[] = [connected, upsert, delta, commit, skip, error, pong, streamEnd];
+
+    expect(incoming.map(m => m.type)).toEqual(['user_message', 'ping']);
+    expect(outgoing.map(m => m.type)).toEqual([
+      'connected',
+      'entry_upsert',
+      'entry_delta',
+      'entry_commit',
+      'entry_skip',
+      'error',
+      'pong',
+      'stream_end',
+    ]);
+  });
+
+  it('admits ListSessionsMessage to IncomingMessage with optional limit and cursor', () => {
+    const bare: ListSessionsMessage = {type: 'list_sessions'};
+    const cursor: SessionCursor = {sessionId: 's0', updatedAt: '2026-01-01T00:00:00.000Z'};
+    const withPaging: ListSessionsMessage = {type: 'list_sessions', limit: 50, before: cursor};
+    const incoming: IncomingMessage[] = [bare, withPaging];
+
+    expect(incoming).toEqual([
+      {type: 'list_sessions'},
+      {type: 'list_sessions', limit: 50, before: {sessionId: 's0', updatedAt: '2026-01-01T00:00:00.000Z'}},
+    ]);
+  });
+
+  it('admits SessionListMessage to OutgoingMessage carrying SessionSummaryFrame rows', () => {
+    const summary: SessionSummaryFrame = {
+      sessionId: 's1',
+      createdAt: '2026-01-01T00:00:00.000Z',
+      updatedAt: '2026-01-01T00:01:00.000Z',
+      entryCount: 4,
+    };
+    const sessionList: SessionListMessage = {
+      type: 'session_list',
+      sessions: [summary],
+    };
+    const outgoing: OutgoingMessage = sessionList;
+
+    expect(outgoing).toEqual({
+      type: 'session_list',
+      sessions: [
+        {
+          sessionId: 's1',
+          createdAt: '2026-01-01T00:00:00.000Z',
+          updatedAt: '2026-01-01T00:01:00.000Z',
+          entryCount: 4,
+        },
+      ],
+    });
+  });
+});
