    const result = validateMessage({type: 'user_message', content: 'hello', chatId: 'c1'});

    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('validates list_sessions frames, admitting optional limit and before cursor while dropping extra fields', () => {
    expect(validateMessage({type: 'list_sessions'})).toEqual({
      valid: true,
      data: {type: 'list_sessions'},
    });

    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z'},
        userId: 'u1',
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 10,
        before: {sessionId: 's1', updatedAt: '2026-01-01T00:00:00.000Z'},
      },
    });

    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 0,
        before: {sessionId: 's2', updatedAt: 1704067200000, extra: 'dropped'},
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 0,
        before: {sessionId: 's2', updatedAt: 1704067200000},
      },
    });

    expect(validateMessage({type: 'list_sessions', limit: 'ten'}).valid).toBe(false);
    expect(validateMessage({type: 'list_sessions', limit: -1}).valid).toBe(false);
    expect(validateMessage({type: 'list_sessions', limit: 1.5}).valid).toBe(false);
    expect(validateMessage({type: 'list_sessions', before: 'not-an-object'}).valid).toBe(false);
    expect(validateMessage({type: 'list_sessions', before: null}).valid).toBe(false);
    expect(
      validateMessage({type: 'list_sessions', before: {sessionId: '', updatedAt: '2026-01-01T00:00:00.000Z'}}).valid
    ).toBe(false);
    expect(
      validateMessage({
        type: 'list_sessions',
        before: {sessionId: 'a'.repeat(129), updatedAt: '2026-01-01T00:00:00.000Z'},
      }).valid
    ).toBe(false);
    expect(
      validateMessage({type: 'list_sessions', before: {sessionId: 's1', updatedAt: 'not-a-date'}}).valid
    ).toBe(false);
    expect(
      validateMessage({type: 'list_sessions', before: {sessionId: 's1', updatedAt: true}}).valid
    ).toBe(false);
  });
});

