import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined) {
    if (typeof message.limit !== 'number' || !Number.isInteger(message.limit) || message.limit < 0) {
      return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
    }
  }

  if (message.before !== undefined) {
    if (typeof message.before !== 'object' || message.before === null || Array.isArray(message.before)) {
      return {valid: false, error: 'list_sessions before must be an object'};
    }

    const before = message.before as Record<string, unknown>;

    if (typeof before.sessionId !== 'string' || before.sessionId.length < 1 || before.sessionId.length > 128) {
      return {valid: false, error: 'before.sessionId must be a string between 1 and 128 characters'};
    }

    if (
      (typeof before.updatedAt !== 'string' && typeof before.updatedAt !== 'number') ||
      Number.isNaN(new Date(before.updatedAt).getTime())
    ) {
      return {valid: false, error: 'before.updatedAt must be a valid timestamp or date string'};
    }
  }

  const data: ListSessionsMessage = {
    type: 'list_sessions',
  };

  if (message.limit !== undefined) {
    data.limit = message.limit as number;
  }

  if (message.before !== undefined) {
    const before = message.before as Record<string, unknown>;
    data.before = {
      sessionId: before.sessionId as string,
      updatedAt: before.updatedAt as string | number,
    };
  }

  return {
    valid: true,
    data,
  };
}

